1	package server
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"fmt"
7		"sort"
8		"strings"
9		"sync"
10		"time"
11	)
12	
13	// ChunkSize is the fixed split size for object bodies. All chunks except the
14	// final one have exactly this many bytes.
15	const ChunkSize = 1048576
16	
17	// MaxObjectSize is the largest accepted object body in bytes.
18	const MaxObjectSize = 67108864
19	
20	// cidPrefix prefixes every content identifier.
21	const cidPrefix = "sha256:"
22	
23	// object is a fully received object held in process memory.
24	type object struct {
25		cid    string
26		size   int
27		chunks [][]byte // raw chunk bytes, in reconstruction order
28		cids   []string // chunk identifiers, parallel to chunks
29	}
30	
31	// pin records a retention guarantee for one object. A nil expiresAt means
32	// the object is retained permanently; otherwise the pin is in force until
33	// the given instant. Pins live in process memory only and are not preserved
34	// across restarts.
35	type pin struct {
36		expiresAt *time.Time
37	}
38	
39	// validPin reports whether p is in force at now. Expired pins are
40	// equivalent to no pin at all.
41	func validPin(p pin, now time.Time) bool {
42		return p.expiresAt == nil || p.expiresAt.After(now)
43	}
44	
45	// blockRef holds one unique stored block. refs counts the live objects that
46	// reference the block; a block repeated within one object still counts once.
47	type blockRef struct {
48		data []byte
49		refs int
50	}
51	
52	// store is an in-process content-addressed object store. Objects are
53	// immutable once inserted; inserts and deletes happen under the write lock
54	// so readers never observe a partially written object. Blocks are stored
55	// once and shared by every object that references them; a block is dropped
56	// as soon as no live object references it.
57	type store struct {
58		mu       sync.RWMutex
59		objects  map[string]*object
60		blocks   map[string]*blockRef
61		pins     map[string]pin
62		metadata map[string][]metadataRevision
63		refs     map[string][]refRevision
64		audit    *auditLog // nil until wired by the HTTP surface
65	}
66	
67	func newStore() *store {
68		return &store{
69			objects:  make(map[string]*object),
70			blocks:   make(map[string]*blockRef),
71			pins:     make(map[string]pin),
72			metadata: make(map[string][]metadataRevision),
73			refs:     make(map[string][]refRevision),
74		}
75	}
76	
77	// chunkCID returns the identifier for one chunk's raw bytes.
78	func chunkCID(data []byte) string {
79		sum := sha256.Sum256(data)
80		return cidPrefix + hex.EncodeToString(sum[:])
81	}
82	
83	// rootCID derives the object identifier from the deterministic manifest: the
84	// total object length followed by the ordered chunk identifiers, encoded as
85	// "size:<N>\n" then one "<cid>\n" line per chunk.
86	func rootCID(size int, cids []string) string {
87		var b strings.Builder
88		fmt.Fprintf(&b, "size:%d\n", size)
89		for _, c := range cids {
90			b.WriteString(c)
91			b.WriteByte('\n')
92		}
93		sum := sha256.Sum256([]byte(b.String()))
94		return cidPrefix + hex.EncodeToString(sum[:])
95	}
96	
97	// put stores the object, or returns the existing one when the same root
98	// identifier is already present. Exactly one concurrent caller observes
99	// created == true for a given object. Newly stored objects register their
100	// unique chunks in the shared block table; repeated chunks within the
101	// object and chunks shared with other objects are stored only once. The
102	// audit event for the action is appended under the same lock, so event
103	// order matches commit order; providerID is set only for remote fetches.
104	func (s *store) put(obj *object, action string, providerID *string) (stored *object, created bool) {
105		s.mu.Lock()
106		defer s.mu.Unlock()
107		if existing, ok := s.objects[obj.cid]; ok {
108			s.audit.append(objectAuditRecord(action, existing, false, providerID))
109			return existing, false
110		}
111		s.objects[obj.cid] = obj
112		seen := make(map[string]bool, len(obj.cids))
113		for i, c := range obj.cids {
114			if b, ok := s.blocks[c]; ok {
115				obj.chunks[i] = b.data // share the stored copy
116				if !seen[c] {
117					b.refs++
118				}
119			} else {
120				s.blocks[c] = &blockRef{data: obj.chunks[i], refs: 1}
121			}
122			seen[c] = true
123		}
124		s.audit.append(objectAuditRecord(action, obj, true, providerID))
125		return obj, true
126	}
127	
128	// get returns the object for a root identifier, or nil when absent.
129	func (s *store) get(cid string) *object {
130		s.mu.RLock()
131		defer s.mu.RUnlock()
132		return s.objects[cid]
133	}
134	
135	// getBlock returns the raw bytes of a stored block, or nil when no live
136	// object references it.
137	func (s *store) getBlock(cid string) []byte {
138		s.mu.RLock()
139		defer s.mu.RUnlock()
140		if b, ok := s.blocks[cid]; ok {
141			return b.data
142		}
143		return nil
144	}
145	
146	// storageStats is a consistent snapshot of the store's occupancy.
147	type storageStats struct {
148		objects      int
149		logicalBytes int
150		blocks       int
151		storedBytes  int
152	}
153	
154	// stats snapshots object and deduplicated block occupancy under one lock
155	// hold, so the four counters always describe the same instant.
156	func (s *store) stats() storageStats {
157		s.mu.RLock()
158		defer s.mu.RUnlock()
159		st := storageStats{objects: len(s.objects), blocks: len(s.blocks)}
160		for _, obj := range s.objects {
161			st.logicalBytes += obj.size
162		}
163		for _, b := range s.blocks {
164			st.storedBytes += len(b.data)
165		}
166		return st
167	}
168	
169	// setPin pins cid with the given expiration, replacing any previous pin. It
170	// reports ok == false when the object does not exist. created is true when
171	// no valid pin was in force at now. The check and the update are atomic
172	// with respect to garbage collection.
173	func (s *store) setPin(cid string, expiresAt *time.Time, now time.Time) (created, ok bool) {
174		s.mu.Lock()
175		defer s.mu.Unlock()
176		if _, exists := s.objects[cid]; !exists {
177			return false, false
178		}
179		existing, found := s.pins[cid]
180		created = !found || !validPin(existing, now)
181		s.pins[cid] = pin{expiresAt: expiresAt}
182		result := "updated"
183		if created {
184			result = "created"
185		}
186		s.audit.append(auditRecord{action: auditPinPut, result: result, cid: strPtr(cid)})
187		return created, true
188	}
189	
190	// removePin deletes the pin for cid, reporting whether a valid pin was in
191	// force at now. Expired pins are removed lazily and reported as absent.
192	func (s *store) removePin(cid string, now time.Time) bool {
193		s.mu.Lock()
194		defer s.mu.Unlock()
195		p, found := s.pins[cid]
196		if !found || !validPin(p, now) {
197			delete(s.pins, cid)
198			return false
199		}
200		delete(s.pins, cid)
201		s.audit.append(auditRecord{action: auditPinDelete, result: "deleted", cid: strPtr(cid)})
202		return true
203	}
204	
205	// pinEntry is one live pin in a listing.
206	type pinEntry struct {
207		cid       string
208		expiresAt *time.Time
209	}
210	
211	// listPins returns the pins in force at now, sorted by cid.
212	func (s *store) listPins(now time.Time) []pinEntry {
213		s.mu.RLock()
214		defer s.mu.RUnlock()
215		entries := []pinEntry{}
216		for cid, p := range s.pins {
217			if validPin(p, now) {
218				entries = append(entries, pinEntry{cid: cid, expiresAt: p.expiresAt})
219			}
220		}
221		sort.Slice(entries, func(i, j int) bool { return entries[i].cid < entries[j].cid })
222		return entries
223	}
224	
225	// collectGarbage removes every object with no valid pin in force at now, or
226	// only counts them when dryRun is true. It returns the affected cids in
227	// lexical order and the sum of their body sizes. The sweep is atomic with
228	// respect to pin updates and object reads.
229	func (s *store) collectGarbage(now time.Time, dryRun bool) (cids []string, totalBytes int) {
230		s.mu.Lock()
231		defer s.mu.Unlock()
232		cids = []string{}
233		for cid, obj := range s.objects {
234			if p, pinned := s.pins[cid]; pinned && validPin(p, now) {
235				continue
236			}
237			cids = append(cids, cid)
238			totalBytes += obj.size
239		}
240		sort.Strings(cids)
241		if !dryRun {
242			for _, cid := range cids {
243				obj := s.objects[cid]
244				delete(s.objects, cid)
245				delete(s.metadata, cid)
246				s.releaseBlocks(obj)
247			}
248			for cid, p := range s.pins {
249				if !validPin(p, now) {
250					delete(s.pins, cid)
251				}
252			}
253		}
254		action := auditGCCollect
255		result := "collected"
256		if dryRun {
257			action = auditGCPreview
258			result = "previewed"
259		}
260		s.audit.append(auditRecord{
261			action:  action,
262			result:  result,
263			objects: intPtr(len(cids)),
264			bytes:   intPtr(totalBytes),
265		})
266		return cids, totalBytes
267	}
268	
269	// releaseBlocks drops the object's block references, removing any block no
270	// other live object uses. The caller must hold the write lock.
271	func (s *store) releaseBlocks(obj *object) {
272		seen := make(map[string]bool, len(obj.cids))
273		for _, c := range obj.cids {
274			if seen[c] {
275				continue
276			}
